<script setup lang="ts">
import {useAccountingAlerts} from './useAccountingAlerts';
import {useAccountingSuperAdmin} from './permissions';
const voucherSuperAdmin=useAccountingSuperAdmin();
import {useAccountingLiveRefresh} from './workspaceRealtime';
import AccountingCurrencyFields from './AccountingCurrencyFields.vue';
import {needsApproval,approvalTypes} from './approvalPolicy';
import {addRowOnEnter} from './entryRows';
import {computed,ref,watch,onBeforeUnmount} from 'vue';
import AccountingSelect from './AccountingSelect.vue';
import AccountingDocument from './AccountingDocument.vue';
import AccountingApprovalPanel from './AccountingApprovalPanel.vue';
import AdminDialog from '../../AdminDialog.vue';
import {useAccountingPermissions} from './permissions';
import {requestKey} from './requestKey';
const props=defineProps<{company:number;book:any;accounts:any[];csrf?:string;openId?:number;defaultKind?:string}>(),emit=defineEmits(['notice','imprest']);
const can=useAccountingPermissions();
const types=[{kind:'contra',code:'CV',name:'Contra transfer',group:'journals',settlement:null,receipt:false},{kind:'cash_payment',code:'CPV',name:'Cash payment',group:'cash_payments',settlement:'Cash',receipt:false},{kind:'cash_receipt',code:'CRV',name:'Cash receipt',group:'cash_receipts',settlement:'Cash',receipt:true},{kind:'bank_payment',code:'BPV',name:'Bank payment',group:'bank_payments',settlement:'Bank',receipt:false},{kind:'bank_receipt',code:'BRV',name:'Bank receipt',group:'bank_receipts',settlement:'Bank',receipt:true},{kind:'expense',code:'EV',name:'Expense voucher',group:'expense_vouchers',settlement:null,receipt:false},{kind:'income',code:'IV',name:'Income voucher',group:'income_vouchers',settlement:null,receipt:true}];
const visibleTypes=computed(()=>types.filter(t=>can(t.group+'.view'))),createTypes=computed(()=>visibleTypes.value.filter(t=>can(t.group+'.create')));
const kind=ref(props.defaultKind||''),status=ref(''),search=ref(''),page=ref(1),records=ref<any>(null),editor=ref<any>(null),loading=ref(false),busy=ref(false),error=ref(''),formError=ref(''),saved=ref(''),confirmation=ref(''),reason=ref('');
const today=new Date().toLocaleDateString('en-CA'),reverseDate=ref(today);let generation=0;
const requiresApproval=computed(()=>needsApproval(props.book,editor.value?.kind||'cash_payment'));
const spec=computed(()=>types.find(t=>t.kind===editor.value?.kind)||types[0]);
const pending=computed(()=>editor.value?.approval&&!['returned','withdrawn'].includes(editor.value.approval.stage));
const editable=computed(()=>editor.value?.status==='draft'&&!pending.value&&can(spec.value.group+(editor.value.id?'.update':'.create')));
const ledgers=computed(()=>props.accounts.filter(a=>!a.imprest_fund&&a.active&&!a.is_group&&(!['Receivable','Payable'].includes(a.account_type)||a.party_kind===(spec.value.receipt?'customer':'supplier'))));
const settlements=computed(()=>ledgers.value.filter(a=>spec.value.kind==='contra'?a.root_type==='Asset'&&['Cash','Bank'].includes(a.account_type):spec.value.settlement?a.root_type==='Asset'&&a.account_type===spec.value.settlement:['Asset','Liability'].includes(a.root_type)));
const offsets=computed(()=>ledgers.value.filter(a=>spec.value.kind==='contra'?a.id!==editor.value?.settlement_id&&a.root_type==='Asset'&&['Cash','Bank'].includes(a.account_type):!['Cash','Bank'].includes(a.account_type)&&(spec.value.settlement||a.root_type===(spec.value.receipt?'Income':'Expense'))));
const minor=(v:any)=>{const text=String(v||'0');if(!/^\d{1,10}(\.\d{1,2})?$/.test(text))return 0;const [whole,fraction='']=text.split('.');return Number(whole)*100+Number(fraction.padEnd(2,'0'));};
const totalMinor=computed(()=>editor.value?.details.reduce((n:number,l:any)=>n+minor(l.amount),0)||0);
const decimal=(n:number)=>Math.trunc(n/100)+'.'+String(n%100).padStart(2,'0');
const money=(v:any)=>Number(v||0).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});
function signature(e:any){return JSON.stringify([e.currency,e.exchange_rate,e.kind,e.posting_date,e.voucher_person,e.reference||'',e.remarks||'',e.settlement_id,e.details.map((l:any)=>[l.account_id,l.description||'',minor(l.amount)])]);}
const unsaved=computed(()=>editor.value&&signature(editor.value)!==saved.value);
function accountName(id:number){const a=props.accounts.find(a=>a.id===id);return a?a.code+' - '+a.name:'Account unavailable';}
async function api(path:string,body?:any){const r=await fetch('/accounting/api/'+path,{method:body?'POST':'GET',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message||'Unable to complete this action.');return d;}
async function load(){const gen=++generation;loading.value=true;error.value='';try{const q=new URLSearchParams({company_id:String(props.company),vouchers:'1',page:String(page.value),status:status.value,search:search.value});if(kind.value)q.set('kind',kind.value);const d=await api('journals?'+q);if(gen===generation)records.value=d;}catch(e){if(gen===generation)error.value=(e as Error).message;}finally{if(gen===generation)loading.value=false;}}
function hydrate(j:any){const type=types.find(t=>t.kind===j.kind)!;const settlement=j.lines.find((l:any)=>type.kind==='contra'?Number(l.credit)>0:type.settlement?props.accounts.find(a=>a.id===l.account_id)?.account_type===type.settlement:Number(type.receipt?l.debit:l.credit)>0);return {...j,settlement_id:settlement?.account_id||'',details:j.lines.filter((l:any)=>l!==settlement).map((l:any)=>({account_id:l.account_id,description:l.description||'',amount:type.receipt?l.credit:l.debit}))};}
async function open(id:number){formError.value='';try{const j=(await api('journals?company_id='+props.company+'&id='+id)).journal;if(j.imprest){emit('imprest',j.id);return;}editor.value=hydrate(j);saved.value=signature(editor.value);}catch(e){error.value=(e as Error).message;}}
function create(){editor.value={kind:createTypes.value.find(t=>t.kind===props.defaultKind)?.kind||createTypes.value[0]?.kind,status:'draft',request_key:requestKey(),currency:props.book?.currency||'PKR',exchange_rate:'1.000000',posting_date:today,voucher_person:'',reference:'',remarks:'',settlement_id:'',details:[{account_id:'',description:'',amount:''}]};saved.value='';formError.value='';}
function changeType(){editor.value.settlement_id='';editor.value.details=[{account_id:'',description:'',amount:''}];}
async function run(action:string){if(busy.value)return;if(action==='post'&&unsaved.value){formError.value='Save all changes before posting.';return;}busy.value=true;formError.value='';try{let d;const e=editor.value;if(action==='save'){
 const lines=e.details.map((l:any)=>({account_id:l.account_id,description:l.description,debit:spec.value.receipt?'0.00':l.amount,credit:spec.value.receipt?l.amount:'0.00'}));
 lines.unshift({account_id:e.settlement_id,description:'Voucher total',debit:spec.value.receipt?decimal(totalMinor.value):'0.00',credit:spec.value.receipt?'0.00':decimal(totalMinor.value)});
 d=await api('journals',{company_id:props.company,id:e.id,version:e.version,request_key:e.request_key,currency:e.currency||props.book?.currency,exchange_rate:e.exchange_rate||'1.000000',kind:e.kind,posting_date:e.posting_date,voucher_person:e.voucher_person,reference:e.reference,remarks:e.remarks,lines});
 }else d=await api('journals/'+e.id+'/'+action,{company_id:props.company,version:e.version,...(action==='reverse'?{reason:reason.value,posting_date:reverseDate.value}:{})});
 confirmation.value='';emit('notice',d.message);if(action==='reverse')await open(e.id);else{editor.value=hydrate(d.journal);saved.value=signature(editor.value);}await load();
 }catch(e){formError.value=(e as Error).message;}finally{busy.value=false;}}
watch(()=>props.company,()=>{editor.value=null;page.value=1;void load();if(props.openId)void open(props.openId);else if(props.defaultKind&&createTypes.value.some(t=>t.kind===props.defaultKind))create();},{immediate:true});
watch(()=>props.openId,id=>{if(id)void open(id);});onBeforeUnmount(()=>generation++);
useAccountingLiveRefresh(()=>load(),()=>!editor.value&&!busy.value);
useAccountingAlerts(error,formError);
</script>
<template><section :class="{'ac-document-open':!!editor}"><div class="ac-section-heading"><div><h2>{{types.find(t=>t.kind===defaultKind)?.name||'Single vouchers'}}</h2><p class="muted">One voucher, multiple detail lines. The settlement total is calculated automatically.</p></div><button v-if="createTypes.length" class="button primary" :disabled="!book||busy" @click="create">+ Create voucher</button></div><p v-if="error" class="notice admin-error" role="alert">{{error}}</p>
<form class="ac-filters" @submit.prevent="page=1;load()"><label>Voucher type<AccountingSelect><select v-model="kind" :disabled="!!defaultKind"><option value="">All voucher types</option><option v-for="t in visibleTypes" :key="t.kind" :value="t.kind">{{t.code}} - {{t.name}}</option></select></AccountingSelect></label><label>Status<AccountingSelect><select v-model="status"><option value="">All statuses</option><option value="draft">Non-posted</option><option value="posted">Posted</option><option value="reversed">Reversed</option></select></AccountingSelect></label><label>Search<input v-model="search" type="search" placeholder="Number, purpose or reference"></label><button class="button" :disabled="loading">Apply filters</button></form>
<p v-if="loading" role="status">Loading vouchers...</p><div v-else-if="records" class="ac-table-wrap"><table class="ac-finance-table"><thead><tr><th>Voucher</th><th>Date</th><th>Purpose / person</th><th>Details</th><th>Status</th><th class="numeric">Total</th><th></th></tr></thead><tbody><tr v-for="row in records.data" :key="row.id"><td><strong>{{row.number}}</strong><small>{{types.find(t=>t.kind===row.kind)?.name}}</small></td><td>{{row.posting_date}}</td><td>{{row.voucher_person}}<small>{{row.reference}}</small></td><td>{{row.lines.length-1}} lines</td><td><span class="ac-badge" :class="row.status==='posted'?'active':'inactive'">{{row.status==='draft'?'Non-posted':row.status}}</span><small v-if="row.approval">{{row.approval.stage.replaceAll('_',' ')}}</small></td><td class="numeric">{{money(row.total)}}</td><td><button class="button" @click="open(row.id)">View voucher</button></td></tr><tr v-if="!records.data.length"><td colspan="7" class="ac-empty-small">No vouchers found.</td></tr></tbody></table></div><div v-if="records" class="ac-pagination"><span>Page {{page}} of {{records.last_page}} &middot; {{records.total}} vouchers</span><button class="button" :disabled="loading||page<=1" @click="page--;load()">Previous</button><button class="button" :disabled="loading||page>=records.last_page" @click="page++;load()">Next</button></div>
<AccountingDocument v-if="editor" :title="editor.number||'Create '+spec.name+' voucher'" :busy="busy" @close="editor=null"><p v-if="formError" class="notice admin-error" role="alert">{{formError}}</p><p class="ac-help">{{editor.status==='draft'?'Non-posted draft: no ledger effect until final posting.':'Posted documents are read only. Corrections require an authorised reversal.'}} For salaries already recorded as payable, select the salary payable ledger instead of recording the expense again.</p>
<form @submit.prevent="run('save')"><fieldset class="ac-journal-fields" :disabled="busy||!editable"><div class="ac-form-grid"><label>Voucher type<AccountingSelect><select v-model="editor.kind" :disabled="!!editor.id||!!defaultKind" @change="changeType"><option v-for="t in (editor.id?visibleTypes:createTypes)" :key="t.kind" :value="t.kind">{{t.code}} - {{t.name}}</option></select></AccountingSelect></label><label>Voucher date<input v-model="editor.posting_date" type="date" required :min="book?.start_date" :max="voucherSuperAdmin?undefined:today"></label><label>Purpose / person<input v-model="editor.voucher_person" required maxlength="150" placeholder="e.g. November salary payments"></label><label>{{spec.settlement?spec.settlement+' account':(spec.kind==='contra'?'Transfer from':'Settlement account')}}<AccountingSelect><select v-model.number="editor.settlement_id" required aria-label="Settlement account"><option value="" disabled>Select account</option><option v-if="editor.settlement_id&&!settlements.some(a=>a.id===editor.settlement_id)" :value="editor.settlement_id">{{accountName(editor.settlement_id)}}</option><option v-for="a in settlements" :key="a.id" :value="a.id">{{a.code}} - {{a.name}}</option></select></AccountingSelect></label><label>Reference<input v-model="editor.reference" maxlength="150"></label><label>Description (optional)<textarea v-model="editor.remarks" rows="2" maxlength="2000"></textarea></label></div>
<AccountingCurrencyFields :model="editor" :company="company" :base="book?.currency||'PKR'" :date="editor.posting_date"/><div class="ac-single-detail-heading"><h3>Voucher details</h3><span>{{editor.details.length}} lines</span></div><div class="ac-table-wrap ac-single-lines"><table class="ac-finance-table"><thead><tr><th>{{spec.kind==='contra'?'Transfer to':'Account'}}</th><th>Employee / person / line note</th><th class="numeric">Amount ({{editor.currency||book?.currency}})</th><th></th></tr></thead><tbody><tr v-for="(line,index) in (editor.details as any[])" :key="index" @keydown.enter="addRowOnEnter($event,index,editor.details,()=>({account_id:'',description:'',amount:''}),editable&&!busy&&spec.kind!=='contra',99)"><td><AccountingSelect><select v-model.number="line.account_id" required :aria-label="'Detail account '+(index+1)"><option value="" disabled>Select account</option><option v-if="line.account_id&&!offsets.some(a=>a.id===line.account_id)" :value="line.account_id">{{accountName(line.account_id)}}</option><option v-for="a in offsets" :key="a.id" :value="a.id">{{a.code}} - {{a.name}}</option></select></AccountingSelect></td><td><input v-model="line.description" maxlength="250" placeholder="e.g. Ali - November salary" :aria-label="'Detail note '+(index+1)"></td><td><input v-model="line.amount" required inputmode="decimal" pattern="[0-9]{1,10}(\.[0-9]{1,2})?" placeholder="0.00" :aria-label="'Detail amount '+(index+1)"></td><td><button v-if="editable" type="button" class="button ac-danger" :disabled="editor.details.length<=1" :aria-label="'Remove detail '+(index+1)" @click="editor.details.splice(index,1)">&times;</button></td></tr></tbody></table></div><button v-if="editable&&spec.kind!=='contra'" type="button" class="button" :disabled="editor.details.length>=99" @click="editor.details.push({account_id:'',description:'',amount:''})">+ Add detail line</button></fieldset>
<div class="ac-journal-totals"><span>Detail total <strong>{{money(decimal(totalMinor))}}</strong></span><span>{{spec.receipt?'Debit':'Credit'}} settlement <strong>{{money(decimal(totalMinor))}}</strong></span></div><div class="ac-form-actions"><button type="button" class="button" :disabled="busy" @click="editor=null">Back</button><button v-if="editable" class="button primary" :disabled="busy||!book||totalMinor<=0">{{busy?'Saving...':'Save draft'}}</button><button v-if="editor.id&&editor.status==='draft'&&!requiresApproval&&!pending&&can(spec.group+'.post')" type="button" class="button" :disabled="busy||unsaved" @click="confirmation='post'">Review posting</button><a v-if="editor.id&&can(spec.group+'.print')" class="button" :href="'/accounting/vouchers/'+editor.id+'/print?company_id='+company" target="_blank" rel="noopener">Print voucher</a><button v-if="editor.status==='posted'&&can(spec.group+'.reverse')" type="button" class="button ac-danger" @click="confirmation='reverse';reason='';reverseDate=today">Reverse voucher</button></div></form>
<AccountingApprovalPanel v-if="editor.id&&(editor.status==='draft'||editor.approval)&&(requiresApproval||editor.approval)&&can('workflow.view')" :company="company" type="journal" :document-id="editor.id" :version="editor.version" :csrf="csrf" :unsaved="unsaved" @notice="emit('notice',$event)" @changed="open(editor.id)"/></AccountingDocument>
<AdminDialog v-if="confirmation" :title="confirmation==='post'?'Post saved voucher':'Reverse voucher'" :busy="busy" @close="confirmation=''"><form @submit.prevent="run(confirmation)"><p v-if="formError" class="notice admin-error" role="alert">{{formError}}</p><p>{{confirmation==='post'?'Post this saved voucher to the ledger?':'The original voucher is preserved and an opposite entry is posted.'}}</p><template v-if="confirmation==='reverse'"><label>Reversal date<input v-model="reverseDate" type="date" required :min="editor.posting_date" :max="today"></label><label>Reason<textarea v-model="reason" required minlength="5" maxlength="2000"></textarea></label></template><div class="ac-form-actions"><button type="button" class="button" :disabled="busy" @click="confirmation=''">Cancel</button><button class="button primary" :disabled="busy">{{busy?'Processing...':'Confirm '+confirmation}}</button></div></form></AdminDialog></section></template>
